package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.List;
import java.util.Locale;

/** Information travels independently from objective truth. */
public final class RumorNetworkEngine {
    private final AppDb db;private final WorldHistoryEngine history;
    public RumorNetworkEngine(AppDb database){db=database;history=new WorldHistoryEngine(database);AppDb.ensureSixZeroSchema(db.getWritableDatabase());}
    public synchronized JSONObject update(int day){JSONObject out=new JSONObject();int born=0,moved=0,learned=0;try{
        history.ingestCanonicalFacts();String profile=db.getActiveMapProfile();JSONArray important=history.important(80);
        for(int importantIndex=0;importantIndex<important.length();importantIndex++){JSONObject event=important.optJSONObject(importantIndex);if(event==null)continue;String eventKey=event.optString("event_key");String key="rumor:"+eventKey;if(db.queryOne("SELECT id FROM rumors WHERE world_profile=? AND rumor_key=?",new String[]{profile,key}).length()>0)continue;ContentValues v=new ContentValues();v.put("world_profile",profile);v.put("rumor_key",key);v.put("source_event_key",eventKey);v.put("origin_location",event.optString("location"));v.put("current_region",event.optString("location"));v.put("statement",mutate(event.optString("summary"),Math.abs(eventKey.hashCode()%3)));v.put("truth_level","parcial");v.put("distortion",10+Math.abs(eventKey.hashCode()%25));v.put("confidence",45+Math.abs((eventKey.hashCode()/7)%40));v.put("secrecy",Math.max(5,70-event.optInt("significance",50)/2));v.put("status","circulating");v.put("born_day",Math.max(1,event.optInt("day_number",day)));v.put("expires_day",day+90);v.put("carriers_json",new JSONArray().put(event.optString("location")).toString());v.put("mutations_json",new JSONArray().put(event.optString("summary")).toString());v.put("updated_at",System.currentTimeMillis());if(db.getWritableDatabase().insertWithOnConflict("rumors",null,v,SQLiteDatabase.CONFLICT_IGNORE)>0)born++;}
        java.util.List<JSONObject> settlements=new LivingSettlementEngine(db).list(200);
        for(JSONObject rumor:list(120)){if(!"circulating".equals(rumor.optString("status")))continue;int bornDay=rumor.optInt("born_day",day),age=Math.max(0,day-bornDay);int distortion=Math.min(90,rumor.optInt("distortion",15)+age/7),confidence=Math.max(12,rumor.optInt("confidence",50)-age/14);String current=rumor.optString("current_region");JSONArray mutations=parseArray(rumor.optString("mutations_json","[]")),carriers=parseArray(rumor.optString("carriers_json","[]"));int propagationStep=age/3;String next=nextRegion(rumor,settlements,propagationStep);if(age>=3&&!next.isEmpty()&&!next.equals(current)){current=next;moved++;if(carriers.length()<30)carriers.put(next);if(propagationStep>mutations.length()-1&&mutations.length()<20)mutations.put(mutationStep(rumor.optString("statement"),propagationStep));}
            ContentValues v=new ContentValues();v.put("current_region",current);v.put("distortion",distortion);v.put("confidence",confidence);v.put("carriers_json",carriers.toString());v.put("mutations_json",mutations.toString());v.put("statement",mutations.length()>1?mutations.optString(mutations.length()-1,rumor.optString("statement")):rumor.optString("statement"));v.put("updated_at",System.currentTimeMillis());if(rumor.optInt("expires_day",0)>0&&day>rumor.optInt("expires_day"))v.put("status","faded");db.getWritableDatabase().update("rumors",v,"id=? AND world_profile=?",new String[]{String.valueOf(rumor.optLong("id")),profile});learned+=teachPresentCharacters(rumor,current,day);}
        out.put("born",born).put("moved",moved).put("learned_by_heroes",learned).put("circulating",new JSONArray(list(30)));
    }catch(Exception e){try{out.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("RumorNetworkEngine","Falha tolerada na camada 6.0.",ignored);}}return out;}

    private int teachPresentCharacters(JSONObject rumor,String currentRegion,int day){String location=db.getSceneState().optString("location");if(location.isEmpty()||currentRegion==null||currentRegion.isEmpty())return 0;String a=normalize(location),b=normalize(currentRegion);if(!(a.contains(b)||b.contains(a)))return 0;if(rumor.optInt("secrecy",20)>65)return 0;int learned=0;for(JSONObject hero:db.listActiveCharacters()){long id=hero.optLong("id");if(id<=0)continue;if(db.queryOne("SELECT id FROM rumor_knowledge WHERE world_profile=? AND rumor_id=? AND knower_kind='hero' AND knower_id=?",new String[]{db.getActiveMapProfile(),String.valueOf(rumor.optLong("id")),String.valueOf(id)}).length()>0)continue;int gate=Math.abs((rumor.optString("rumor_key")+":"+id+":"+day).hashCode()%100);if(gate>Math.max(25,75-rumor.optInt("secrecy",20)))continue;teachHero(rumor.optLong("id"),id,"conversa local em "+location,day);learned++;}return learned;}
    private static String nextRegion(JSONObject rumor,java.util.List<JSONObject> settlements,int step){if(settlements==null||settlements.isEmpty()||step<=0)return rumor.optString("current_region");int index=Math.floorMod((rumor.optString("rumor_key")+":"+step).hashCode(),settlements.size());JSONObject s=settlements.get(index);String region=s.optString("region").trim();return region.isEmpty()?s.optString("name"):region;}
    private static String mutationStep(String statement,int step){String base=statement==null?"":statement.replaceFirst("^(Dizem que|Corre a notícia de que|Há quem jure que)\\s*","").trim();if(step%3==0)return "Alguns afirmam que "+lowerFirst(base);if(step%3==1)return "A versão que circula agora diz que "+lowerFirst(base);return "O boato chegou distorcido: "+lowerFirst(base);}
    private static JSONArray parseArray(String raw){try{return new JSONArray(raw==null?"[]":raw);}catch(Exception ignored){return new JSONArray();}}
    private static String normalize(String s){return (s==null?"":s.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}0-9]+"," ").trim());}

    public List<JSONObject> list(int limit){return db.queryList("SELECT * FROM rumors WHERE world_profile=? AND status='circulating' ORDER BY confidence DESC,born_day DESC LIMIT "+Math.max(1,Math.min(500,limit)),new String[]{db.getActiveMapProfile()});}
    public JSONArray forMaster(int limit){JSONArray out=new JSONArray();for(JSONObject r:list(limit)){JSONObject x=new JSONObject();try{x.put("id",r.optLong("id")).put("statement",r.optString("statement")).put("truth_level",r.optString("truth_level")).put("confidence",r.optInt("confidence")).put("distortion",r.optInt("distortion")).put("origin",r.optString("origin_location")).put("source_event_key",r.optString("source_event_key"));}catch(Exception ignored){AppLog.ignored("RumorNetworkEngine","Falha tolerada na camada 6.0.",ignored);}out.put(x);}return out;}
    public synchronized void teachHero(long rumorId,long characterId,String source,int day){String token=String.valueOf(characterId);ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("rumor_id",rumorId);v.put("knower_kind","hero");v.put("knower_id",token);v.put("knowledge_state","heard");v.put("believed_confidence",55);v.put("learned_day",day);v.put("source_name",source==null?"":source);db.getWritableDatabase().insertWithOnConflict("rumor_knowledge",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    public JSONArray knownByHero(long characterId,int limit){return new JSONArray(db.queryList("SELECT r.id,r.statement,r.current_region,r.status,r.born_day,r.expires_day,rk.knowledge_state,rk.believed_confidence,rk.learned_day,rk.source_name FROM rumor_knowledge rk JOIN rumors r ON r.id=rk.rumor_id WHERE rk.world_profile=? AND rk.knower_kind='hero' AND rk.knower_id=? ORDER BY rk.learned_day DESC LIMIT "+Math.max(1,Math.min(300,limit)),new String[]{db.getActiveMapProfile(),String.valueOf(characterId)}));}
    public JSONObject context(){JSONObject o=new JSONObject();try{o.put("circulating",forMaster(30)).put("contract","Rumor não é fato. O Mestre recebe truth_level internamente; personagens só recebem rumores que conhecem.");}catch(Exception ignored){AppLog.ignored("RumorNetworkEngine","Falha tolerada na camada 6.0.",ignored);}return o;}
    private static String mutate(String s,int mode){String x=s==null?"":s.trim();if(x.length()>480)x=x.substring(0,480)+"…";if(mode==0)return "Dizem que "+lowerFirst(x);if(mode==1)return "Corre a notícia de que "+lowerFirst(x);return "Há quem jure que "+lowerFirst(x);}
    private static String lowerFirst(String x){if(x.isEmpty())return x;return x.substring(0,1).toLowerCase(Locale.ROOT)+x.substring(1);}
}
